@dataclasses.dataclass(frozen=True)
class VectorSpaceWithBasis:
  """A vector space with a given basis."""

  basis: Sequence[BasisDirection]

  def __post_init__(self):
    object.__setattr__(self, "basis",
                       sorted(self.basis))

  def __getitem__(self, idx: int) -> BasisDirection:
    return self.basis[idx]

  def __len__(self) -> int:
    return len(self.basis)

  def __contains__(self, direction: BasisDirection) -> bool:
    return direction in self.basis

  def null_vector(self) -> VectorInBasis:
    return VectorInBasis(self.basis, np.zeros(len(self.basis)))

  def vector_from_basis_direction(
      self, direction: BasisDirection) -> VectorInBasis:
    idx = list(self.basis).index(direction)
    magnitudes = np.zeros(len(self.basis))
    magnitudes[idx] = 1.0
    return VectorInBasis(self.basis, magnitudes)

  def make_vector(self, magnitudes: np.ndarray) -> VectorInBasis:
    return VectorInBasis(self.basis, magnitudes)

  def project(self, vector: VectorInBasis) -> VectorInBasis:
    return vector.project(self)


def join_vector_spaces(
    spaces: Iterable[VectorSpaceWithBasis]) -> VectorSpaceWithBasis:
  """Joins vector spaces into a single space with the union basis."""
  basis = []
  for space in spaces:
    basis.extend(space.basis)
  # Deduplicate while preserving order; VectorSpaceWithBasis sorts anyway.
  seen = set()
  unique_basis = []
  for d in basis:
    if d not in seen:
      seen.add(d)
      unique_basis.append(d)
  return VectorSpaceWithBasis(unique_basis)


def join_vectors(*vectors: VectorInBasis) -> VectorInBasis:
  """Joins vectors with disjoint bases into a single vector."""
  basis = []
  for v in vectors:
    basis.extend(v.basis_directions)
  joint_space = VectorSpaceWithBasis(basis)
  n = vectors[0].magnitudes.shape[:-1]
  out = np.zeros(n + (len(joint_space),))
  for v in vectors:
    indices = [list(joint_space.basis).index(d) for d in v.basis_directions]
    out[..., indices] = v.magnitudes
  return VectorInBasis(joint_space.basis, out)

