@dataclasses.dataclass(frozen=True)
class VectorSpaceWithBasis:
  """A vector space with a given basis."""

  basis: Sequence[BasisDirection]

  def __post_init__(self):
    object.__setattr__(self, "basis",
                       sorted(self.basis))

  @property
  def num_dims(self) -> int:
    return len(self.basis)

  def null_vector(self) -> VectorInBasis:
    return VectorInBasis(self.basis, np.zeros(self.num_dims))

  def vector_from_values(
      self,
      values: dict[BasisDirection, float],
  ) -> VectorInBasis:
    magnitudes = np.zeros(self.num_dims)
    for direction, value in values.items():
      magnitudes[self.basis.index(direction)] = value
    return VectorInBasis(self.basis, magnitudes)

  def make_unit(self, direction: BasisDirection) -> VectorInBasis:
    return self.vector_from_values({direction: 1.0})

  def __eq__(self, other: "VectorSpaceWithBasis") -> bool:
    return list(self.basis) == list(other.basis)

  def __add__(
      self, other: "VectorSpaceWithBasis") -> "VectorSpaceWithBasis":
    return join_vector_spaces([self, other])


def join_vector_spaces(
    spaces: Iterable[VectorSpaceWithBasis]) -> VectorSpaceWithBasis:
  basis_directions = []
  for space in spaces:
    basis_directions.extend(space.basis)
  if len(set(basis_directions)) != len(basis_directions):
    raise ValueError(
        f"Basis directions must be unique. Got {basis_directions}.")
  return VectorSpaceWithBasis(basis_directions)


def join_vectors(*vectors: VectorInBasis) -> VectorInBasis:
  basis_directions = []
  magnitudes = []
  for v in vectors:
    basis_directions.extend(v.basis_directions)
    magnitudes.append(v.magnitudes)
  return VectorInBasis(basis_directions, np.concatenate(magnitudes, axis=-1))

