def _get_trunk_args_kwargs(self, sample, input_key):
    if input_key in self.trunk_field_args:
        args_keys = self.trunk_field_args[input_key]
        kwargs_keys = self.trunk_field_kwargs[input_key]
    elif None in self.trunk_field_args:
        args_keys = self.trunk_field_args[None]
        kwargs_keys = self.trunk_field_kwargs[None]
    else:
        raise KeyError(f"No trunk_fields specified for input_key: {input_key}")
    if isinstance(sample, Mapping):
        args = [sample[k] for k in args_keys]
        kwargs = {k: sample[v] for k, v in kwargs_keys.items()}
    else:
        args = [getattr(sample, k) for k in args_keys]
        kwargs = {k: getattr(sample, v) for k, v in kwargs_keys.items()}
    return args, kwargs

def forward(self, inputs):
    if isinstance(inputs, Mapping):
        output = {}
        for input_key, sample in inputs.items():
            self.input_key = input_key
            self.outputs = {}
            args, kwargs = self._get_trunk_args_kwargs(sample, input_key)
            if self.handle_list_inputs and isinstance(args[0], list):
                for elem in args[0]:
                    self.trunk([elem], **kwargs)
            else:
                self.trunk(*args, **kwargs)
            output.update(copy.copy(self.outputs))
        self.input_key = None
        self.outputs = {}
        return output
    else:
        # single sample, infer input_key
        if None in self.trunk_field_args:
            input_key = None
        elif len(self.trunk_field_args) == 1:
            input_key = list(self.trunk_field_args.keys())[0]
        else:
            raise ValueError(
                "Single sample forward with multiple trunk_fields is ambiguous, "
                "pass a dict of input_key to sample."
            )
        # resolve actual key for head filtering
        if input_key is None:
            # try to infer from sample if it has input_key attr
            self.input_key = getattr(inputs, "input_key", None)
        else:
            self.input_key = input_key
        self.outputs = {}
        args, kwargs = self._get_trunk_args_kwargs(inputs, input_key)
        self.trunk(*args, **kwargs)
        out = copy.copy(self.outputs)
        self.input_key = None
        self.outputs = {}
        return out

