           ) -> "VectorInBasis":
  """Project onto a subset of basis directions, dropping the rest."""
  basis_directions = list(basis_directions)
  idx = [self.basis_directions.index(bd) for bd in basis_directions]
  magnitudes = np.take(self.magnitudes, idx, -1)
  return VectorInBasis(basis_directions, magnitudes)

