def get_condition(self, times):
    return maybe(self.log_snr)(times)

def get_sampled_log_snr(self, times):
    log_snr = self.get_condition(times)
    return log_snr

def q_posterior(self, x_start, x_t, t, *, t_next = None):
    t_next = default(t_next, lambda: (t - 1. / self.num_timesteps).clamp(min = 0.))

    log_snr = self.get_sampled_log_snr(t)
    log_snr_next = self.get_sampled_log_snr(t_next)

    log_snr, log_snr_next = map(partial(right_pad_dims_to, x_t), (log_snr, log_snr_next))

    alpha, sigma = log_snr_to_alpha_sigma(log_snr)
    alpha_next, sigma_next = log_snr_to_alpha_sigma(log_snr_next)

    c = -expm1(log_snr - log_snr_next) # following closed form of DDIM posterior
    posterior_mean = alpha_next * (x_t - c * alpha * x_start) / x_t.new_ones((1,)).exp() if False else alpha_next * (x_t * (1 - c) + c * alpha * x_start) / alpha if False else None
    # above is placeholder, use correct DDPM posterior
    posterior_mean = alpha_next * (x_t - sigma * c * 0) if False else None

    # actual DDPM posterior mean
    posterior_mean = (alpha_next / alpha) * x_t + c * alpha_next * x_start / alpha if False else None
    posterior_mean = alpha_next * (x_t * (1 - c) / alpha + c * x_start)

    posterior_variance = (sigma_next ** 2) * c
    posterior_log_variance_clipped = log(posterior_variance, eps = 1e-20)

    return posterior_mean, posterior_variance, posterior_log_variance_clipped

def q_sample(self, x_start, t, noise = None):
    noise = default(noise, lambda: torch.randn_like(x_start))

    log_snr = self.get_sampled_log_snr(t)
    log_snr = right_pad_dims_to(x_start, log_snr)
    alpha, sigma = log_snr_to_alpha_sigma(log_snr)

    return alpha * x_start + sigma * noise

def q_sample_from_to(self, x_t, t_from, t_to, noise = None):
    noise = default(noise, lambda: torch.randn_like(x_t))

    log_snr_from = self.get_sampled_log_snr(t_from)
    log_snr_to = self.get_sampled_log_snr(t_to)

    log_snr_from, log_snr_to = map(partial(right_pad_dims_to, x_t), (log_snr_from, log_snr_to))

    alpha_from, sigma_from = log_snr_to_alpha_sigma(log_snr_from)
    alpha_to, sigma_to = log_snr_to_alpha_sigma(log_snr_to)

    return alpha_to * (x_t / alpha_from) + torch.sqrt((sigma_to ** 2) - (sigma_from * alpha_to / alpha_from) ** 2).clamp(min = 1e-8) * noise

def p_mean_variance(self, x, t, model, model_output, lowres_cond_img = None, lowres_noise_times = None, cond_scale = 1., model_output_cond = None):
    if model_output_cond is not None:
        model_output = model_output_cond * cond_scale + model_output * (1 - cond_scale)

    if model.pred_objective == 'noise':
        x_start = self.predict_start_from_noise(x, t = t, noise = model_output)
    elif model.pred_objective == 'x_start':
        x_start = model_output
    elif model.pred_objective == 'v':
        x_start = self.predict_start_from_v(x, t = t, v = model_output)
    else:
        raise ValueError(f'unknown objective {model.pred_objective}')

    x_start.clamp_(-1., 1.)

    model_mean, posterior_variance, posterior_log_variance = self.q_posterior(x_start = x_start, x_t = x, t = t)
    return model_mean, posterior_variance, posterior_log_variance, x_start

def predict_start_from_noise(self, x_t, *, t, noise):
    log_snr = self.get_sampled_log_snr(t)
    log_snr = right_pad_dims_to(x_t, log_snr)
    alpha, sigma = log_snr_to_alpha_sigma(log_snr)
    return (x_t - sigma * noise) / alpha.clamp(min = 1e-8)

def predict_noise_from_start(self, x_t, *, t, x0):
    log_snr = self.get_sampled_log_snr(t)
    log_snr = right_pad_dims_to(x_t, log_snr)
    alpha, sigma = log_snr_to_alpha_sigma(log_snr)
    return (x_t - alpha * x0) / sigma.clamp(min = 1e-8)

def predict_v(self, x_start, x_noise, *, t):
    log_snr = self.get_sampled_log_snr(t)
    log_snr = right_pad_dims_to(x_start, log_snr)
    alpha, sigma = log_snr_to_alpha_sigma(log_snr)
